# Completa la línea marcada y compruébala con py check.
def respuesta(parche, filtro):
    total = 0
    for i in range(3):
        for j in range(3):
            total += 0   # ← cambia esta línea: parche[i][j] por filtro[i][j]
    return total

borde_vertical = [[-1, 0, 1], [-2, 0, 2], [-1, 0, 1]]
print(respuesta([[0, 0, 1], [0, 0, 1], [0, 0, 1]], borde_vertical))   # 4
